INSERT INTO memories(kind, content) VALUES('kb', 'Vàng và USD/DXY thường nghịch đảo: USD mạnh lên thì XAU/USD chịu áp lực giảm và ngược lại. Khi phân tích luôn kiểm tra bối cảnh đồng USD.');
INSERT INTO memories(kind, content) VALUES('kb', 'Lãi suất thực (lợi suất TPCP Mỹ trừ lạm phát kỳ vọng) là driver số 1 của vàng: real yield tăng thì vàng kém hấp dẫn vì không trả lãi; real yield giảm thì vàng hưởng lợi.');
INSERT INTO memories(kind, content) VALUES('kb', 'Fed dovish (gợi ý cắt giảm, lo suy thoái) thì vàng tăng; Fed hawkish (diều hâu, giữ lãi suất cao lâu) thì vàng giảm. Theo dõi phát biểu FOMC và dot plot.');
INSERT INTO memories(kind, content) VALUES('kb', 'CPI/PCE cao hơn dự báo thì phức tạp 2 mặt: lạm phát cao hỗ trợ vàng nhưng khiến Fed hawkish hơn (xấu cho vàng ngắn hạn). Luôn nêu cả hai mặt.');
INSERT INTO memories(kind, content) VALUES('kb', 'NFP và thất nghiệp mạnh hơn dự báo thì USD mạnh, vàng thường giảm; ngược lại NFP yếu thì vàng tăng vì kỳ vọng Fed nới lỏng.');
INSERT INTO memories(kind, content) VALUES('kb', 'Địa chính trị leo thang, chiến tranh, khủng hoảng ngân hàng thì dòng tiền trú ẩn chảy vào vàng (risk-off). Khi risk-on (chứng khoán tăng, lợi suất tăng) vàng thường yếu đi.');
INSERT INTO memories(kind, content) VALUES('kb', 'Ngân hàng trung ương (Trung Quốc, Ấn Độ, Ba Lan...) mua vàng đều đặn tạo lực đỡ dài hạn, giảm độ sâu các nhịp điều chỉnh.');
INSERT INTO memories(kind, content) VALUES('kb', 'Phiên Á biên hẹp, hay quét 2 đầu; phiên London tạo xu hướng thật (breakout); phiên New York thanh khoản cao nhất, tin Mỹ ra giá chạy mạnh và trượt giá (slippage) cao.');
INSERT INTO memories(kind, content) VALUES('kb', 'Tránh vào lệnh 15-30 phút quanh NFP, CPI, FOMC trừ khi chuyên đánh tin: spread giãn, quét SL cả hai chiều rồi mới chọn hướng thật.');
INSERT INTO memories(kind, content) VALUES('kb', 'BOS là phá vỡ cấu trúc theo xu hướng, CHoCH là đổi tính chất báo đảo chiều sớm. Entry đẹp thường ở pullback về vùng BOS/CHoCH, không đuổi giá giữa đường.');
INSERT INTO memories(kind, content) VALUES('kb', 'Liquidity sweep: giá hay quét đỉnh/đáy cũ để hốt SL rồi mới đi hướng thật. Nến râu dài qua đỉnh/đáy cũ rồi đóng ngược vào trong là tín hiệu bẫy.');
INSERT INTO memories(kind, content) VALUES('kb', 'FVG/imbalance (khoảng trống giữa 3 nến) thường bị lấp lại: vùng FVG khung lớn là nơi đặt buy limit/sell limit tốt cho swing.');
INSERT INTO memories(kind, content) VALUES('kb', 'Đỉnh/đáy swing khung 4H và 1D là S/R quan trọng nhất cho swing: entry swing đẹp nằm gần đó kèm projection xu hướng, không vào giữa vùng không có mốc.');
INSERT INTO memories(kind, content) VALUES('kb', 'Quản trị vốn: rủi ro 1-2% tài khoản mỗi lệnh; SL theo cấu trúc (dưới đáy/trên đỉnh gần nhất + đệm ATR), không dời SL xa khi lệnh lỗ.');
INSERT INTO memories(kind, content) VALUES('kb', 'Scalping XAU/USD hợp khung 1m-5m khi biên rõ và spread thấp; swing hợp 4H-1D giữ trên 1 giờ tới vài ngày, TP theo mốc cấu trúc kế tiếp, dùng lệnh chờ thay vì đuổi giá.');
